  try { return Java.loadClass(n); } catch (e1) {}
  return Packages.java.lang.Class.forName(n);
}
function B(v){ return String(v) === 'true'; }
function mOf(cls, name){
  var ms = cls.getDeclaredMethods();
  for (var i = 0; i < ms.length; i++) { if (String(ms[i].getName()) === name) { return ms[i]; } }
  return null;
}
