  var a = Arr.newInstance(Obj, vals.length);
  for (var i = 0; i < vals.length; i++) { a[i] = vals[i]; }
  m.setAccessible(true);
  return m.invoke(tgt, a);
}
function stat(cls, name){
  var f = fOf(cls, name);
  f.setAccessible(true);
  return f.get(null);
}
